<script lang="ts">
 import {sessionRequest} from '$lib/admin';
 let email=$state(''),password=$state(''),busy=$state(false),error=$state('');
 async function login(e:SubmitEvent){e.preventDefault();busy=true;error='';try{await sessionRequest('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password})});location.assign('/');}catch(e){error=e instanceof Error?e.message:'Unable to sign in';}finally{busy=false;}}
</script>
<svelte:head><title>Sign in · OmieBot AI Trading</title><meta name="robots" content="noindex"/></svelte:head>
<main><a href="/" class="brand">Omie<span>Bot</span><small>AI TRADING</small></a><section><span class="eyebrow">YOUR RESEARCH WORKSPACE</span><h1>Welcome back.</h1><p>Connect to your hive, review its evidence and manage your trading controls.</p><form onsubmit={login}><label>Email<input type="email" autocomplete="username" bind:value={email} required/></label><label>Password<input type="password" autocomplete="current-password" bind:value={password} required minlength="8"/></label>{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="primary" disabled={busy}>{busy?'Signing in…':'Sign in securely →'}</button></form><div class="divider">or continue with</div><div class="social"><a href="/api/auth/google">Google</a><a href="/api/auth/github">GitHub</a></div><p class="note">Access is assigned by the server. Signing in does not enable live trading.</p><a class="back" href="/">← Back to terminal</a></section><footer>OmieBot AI Trading · Evidence before execution</footer></main>
